#ifndef TUNE_PLAYER_H
#define TUNE_PLAYER_H

#include <stdint.h>

/*
 * Small tune engine for the speaker: the startup sound and the warning sounds
 * (fault beep, critical battery). Pure C with no HAL and no RTOS, so the Unity
 * tests in Tests/TunePlayer run exactly the code TomTask runs.
 *
 * A tune is a const table of {frequency, duration} notes (frequency 0 = rest).
 * The player renders one note at a time:
 *   - a sine from a phase accumulator (the method of the old fault beep); the
 *     phase restarts at 0 on every note;
 *   - a note lasts duration_ms * fs / 1000 frames (48 frames per ms at 48 kHz)
 *     and the player moves on by counting frames, so a tune always lasts
 *     exactly the sum of its note durations;
 *   - every note fades in and out linearly over TUNE_FADE_MS (at most half the
 *     note each way), so the first and last sample of a note are 0: no clicks;
 *   - a rest is silence;
 *   - the amplitude is fixed at TUNE_AMPLITUDE: no tune is scaled by the UI
 *     volume or mute. Only tunes of priority >= TUNE_PRIORITY_FAULT (fault
 *     beep, critical battery) are warnings; the startup sound is not.
 */

#define TUNE_AMPLITUDE   16384      /* 50 % of full scale, fixed: tunes are NOT scaled by the UI volume */
#define TUNE_FADE_MS     5U         /* linear fade-in and fade-out per note: no clicks */

/* tune_t.priority. Priority >= TUNE_PRIORITY_FAULT marks a WARNING. A queued
 * tune can only be replaced by one of at least the same priority, so a
 * waiting warning is never pushed out by an ordinary tune. */
#define TUNE_PRIORITY_NORMAL    0U  /* startup sound */
#define TUNE_PRIORITY_FAULT     1U  /* fault beep */
#define TUNE_PRIORITY_CRITICAL  2U  /* critical battery */

/** One note of a tune. freq_hz 0 is a rest (silence for duration_ms). */
typedef struct
{
    uint16_t freq_hz;
    uint16_t duration_ms;
} tune_note_t;

/** A tune: a const note table and its priority (TUNE_PRIORITY_*). */
typedef struct
{
    const tune_note_t *notes;
    uint8_t count;
    uint8_t priority;
} tune_t;

extern const tune_t g_tune_startup;   /* C5 523 Hz 120 ms, E5 659 120, G5 784 120, C6 1047 260 = 620 ms */
extern const tune_t g_tune_critical;  /* G5 784 160, rest 20, E5 659 160, rest 20, C5 523 160 = 520 ms */
extern const tune_t g_tune_fault;     /* 1000 Hz 200 ms (the old fault beep as a one-note tune) */

/**
 * Player state. Caller-owned (TomTask keeps one static in .bss); use the
 * functions below rather than writing the fields.
 */
typedef struct
{
    const tune_t *current;   /* tune being played, NULL = idle */
    const tune_t *pending;   /* the one queued tune, NULL = none */
    uint8_t note;            /* index of the note being played in current */
    uint32_t frame;          /* frames of that note already rendered */
    uint32_t note_frames;    /* length of that note in frames */
    uint32_t fade_frames;    /* fade-in and fade-out length of that note in frames */
    float phase;             /* sine phase in radians, restarts at 0 on each note */
    float phase_inc;         /* 2*pi*f/fs of that note */
    uint32_t fs_hz;          /* output sample rate */
} tune_player_t;

/**
 * @brief Initialise an idle player.
 * @param p Player state. NULL is safely ignored.
 * @param fs_hz Output sample rate (TomTask: 48000).
 */
void tune_player_init(tune_player_t *p, uint32_t fs_hz);

/**
 * @brief Ask for a tune. A request while a tune plays is queued once, not dropped:
 *        - idle: the tune starts now;
 *        - the same tune is already playing or queued: nothing changes (returns 0);
 *        - nothing queued: the tune is queued and starts when the current one ends;
 *        - another tune is queued: it is replaced only if the new tune's priority
 *          is at least as high, otherwise the new request is dropped (returns 0).
 *        A playing tune is never cut short here (tune_player_stop() does that).
 * @param p Player state.
 * @param t Tune to play (one of the const tunes; compared by address).
 * @return 1 when the tune is now playing or queued, 0 when it was ignored or
 *         dropped (also for a NULL player, a NULL tune or a tune with no notes).
 */
uint8_t tune_player_request(tune_player_t *p, const tune_t *t);

/**
 * @brief Stop at once: clears the current and the queued tune. The next
 *        render call returns silence.
 * @param p Player state. NULL is safely ignored.
 */
void tune_player_stop(tune_player_t *p);

/**
 * @brief Report whether a tune is playing or queued.
 * @param p Player state.
 * @return 1 while a tune is playing or queued, 0 when idle or p is NULL.
 */
uint8_t tune_player_busy(const tune_player_t *p);

/**
 * @brief Read the tune being played.
 * @param p Player state.
 * @return The current tune, or NULL when idle or p is NULL.
 */
const tune_t *tune_player_current(const tune_player_t *p);

/**
 * @brief Render the next n mono samples of the current tune.
 *
 * Samples after the tune ends are 0. When the tune ends inside the buffer the
 * queued tune (if any) becomes current at once, but its first sample is
 * rendered by the NEXT call; the rest of this buffer is silence. One call
 * therefore never mixes two tunes.
 *
 * @param p Player state (NULL renders silence).
 * @param mono Output buffer of n samples. NULL is safely ignored.
 * @param n Number of samples to write.
 * @return How many samples belonged to a tune (0 = idle, the buffer is all zeros).
 */
uint32_t tune_player_render(tune_player_t *p, int16_t *mono, uint32_t n);

/**
 * @brief Total length of a tune, rests included.
 * @param t Tune.
 * @return Sum of the note durations in ms, or 0 for NULL or a tune with no notes.
 */
uint32_t tune_duration_ms(const tune_t *t);

#endif
